mapper.select:
SELECT sm.sku_code AS skuCode, COALESCE(SUM(oi.quantity), 0) AS totalQuantity FROM erp_order o INNER JOIN erp_order_item oi ON o.id = oi.order_id INNER JOIN sku_mapping sm ON oi.platform_item_id = sm.platform_item_id WHERE o.erp_status = 'DELIVERED' AND o.platform_created_at >= #{startTime} AND sm.sku_code IN
#{code}
GROUP BY sm.sku_code

SELECT o.platform, sm.sku_code AS skuCode, SUM(oi.quantity) AS totalQuantity FROM erp_order o INNER JOIN erp_order_item oi ON o.id = oi.order_id INNER JOIN sku_mapping sm ON oi.platform_item_id = sm.platform_item_id WHERE o.fulfillment_type = 'FBS' AND o.erp_status NOT IN ('CANCELED', 'RETURNED') AND o.platform_created_at >= #{startTime}
AND o.platform IN
#{p}
AND sm.sku_code IN
#{sku}
GROUP BY o.platform, sm.sku_code

SELECT o.platform, sm.sku_code AS skuCode, SUM(oi.quantity) AS totalQuantity FROM erp_order o INNER JOIN erp_order_item oi ON o.id = oi.order_id INNER JOIN sku_mapping sm ON oi.platform_item_id = sm.platform_item_id WHERE o.fulfillment_type = 'FBS' AND o.erp_status NOT IN ('CANCELED', 'RETURNED') AND o.platform_created_at >= #{startTime} AND o.platform_created_at < #{endTime}
AND o.platform IN
#{p}
